// AWI: welcome screen perkenalan AWI + jingle, hanya di beranda, sekali per kunjungan (sessionStorage), dilewati untuk bot. Dipasang Claude 11 Nov 2026.
function awi_welcome_out() {
	static $done = false;
	if ( $done || is_admin() || ! is_front_page() ) {
		return;
