#awi-wel .w-name{font-size:clamp(64px,19vw,128px);font-weight:900;line-height:.95;letter-spacing:4px;margin:4px 0 6px;display:flex;justify-content:center;gap:.04em}
#awi-wel .w-name span{display:inline-block;opacity:0;transform:translateY(30px) rotateX(70deg);animation:wLet .55s cubic-bezier(.2,1.3,.4,1) forwards;background:linear-gradient(180deg,#fff 30%,#c7d2fe);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:none}
#awi-wel .w-name span:nth-child(1){animation-delay:1.1s}#awi-wel .w-name span:nth-child(2){animation-delay:1.22s}#awi-wel .w-name span:nth-child(3){animation-delay:1.34s}
@keyframes wLet{to{opacity:1;transform:none}}
#awi-wel .w-full{font-size:clamp(15px,4vw,20px);font-weight:600;opacity:0;animation:wIn .5s ease 1.7s forwards}
#awi-wel .w-role{display:inline-block;margin-top:8px;font-size:clamp(12px,3.3vw,15px);color:#cbd5e1;padding:6px 14px;border:1px solid rgba(255,255,255,.25);border-radius:999px;background:rgba(255,255,255,.06);opacity:0;animation:wIn .5s ease 2.05s forwards}
#awi-wel .w-tag{position:absolute;left:0;right:0;bottom:160px;text-align:center;z-index:4;font-size:clamp(26px,8vw,46px);font-weight:900;font-style:italic;letter-spacing:.5px;text-shadow:0 4px 18px rgba(0,0,0,.7);opacity:0;transform:scale(.7);animation:wPop .6s cubic-bezier(.2,1.5,.4,1) 2.9s forwards}
#awi-wel .w-tag b{color:#5eead4}
@keyframes wPop{to{opacity:1;transform:none}}
#awi-wel .w-chips{position:absolute;left:0;right:0;bottom:78px;z-index:4;display:flex;flex-wrap:wrap;justify-content:center;gap:6px;padding:0 14px}
#awi-wel .w-chips span{font-size:clamp(11px,3vw,14px);font-weight:700;padding:6px 11px;border-radius:999px;background:rgba(8,20,34,.85);border:1px solid rgba(94,234,212,.5);opacity:0;transform:translateY(10px);animation:wIn .4s ease forwards}
#awi-wel .w-chips span:nth-child(1){animation-delay:3.4s}#awi-wel .w-chips span:nth-child(2){animation-delay:3.55s}#awi-wel .w-chips span:nth-child(3){animation-delay:3.7s}
@keyframes wIn{to{opacity:1;transform:none}}
#awi-wel .w-bar{position:absolute;left:0;right:0;bottom:8px;height:62px;z-index:6;display:flex;align-items:center;justify-content:center;padding:0 14px 6px}
#awi-wel .w-go{position:relative;overflow:hidden;border:0;border-radius:999px;background:#25d366;color:#04140a;font-weight:800;font-size:16px;padding:12px 26px;cursor:pointer;box-shadow:0 6px 20px rgba(37,211,102,.35);opacity:0;animation:wIn .4s ease 3.9s forwards}
#awi-wel .w-go i{position:absolute;left:0;bottom:0;height:3px;background:rgba(0,0,0,.35);width:0;animation:wProg 3.4s linear 4.1s forwards}
@keyframes wProg{to{width:100%}}
#awi-wel .w-top{position:absolute;top:10px;left:10px;right:10px;display:flex;justify-content:space-between;z-index:7}
#awi-wel .w-top button{border:1px solid rgba(255,255,255,.3);background:rgba(0,0,0,.35);color:#fff;border-radius:999px;padding:8px 14px;font-size:13px;font-weight:700;cursor:pointer;backdrop-filter:blur(4px)}
#awi-wel .w-snd.pulse{animation:wPulse 1.2s ease-in-out infinite}
@keyframes wPulse{50%{box-shadow:0 0 0 6px rgba(94,234,212,.25);border-color:#5eead4}}
@media (min-width:900px) and (min-aspect-ratio:4/3){
 #awi-wel .w-stage{flex-direction:row;align-items:flex-end;justify-content:flex-start}
 #awi-wel .w-disc,#awi-wel .w-ring{left:28%;bottom:10vh;width:min(46vh,430px)}
 #awi-wel .w-awi{margin-left:14%;height:80vh}
 #awi-wel .w-txt{top:22vh;left:48%;right:4%;text-align:left}
 #awi-wel .w-name{justify-content:flex-start}
 #awi-wel .w-tag{left:48%;right:4%;text-align:left;bottom:36vh}
 #awi-wel .w-chips{left:48%;right:4%;justify-content:flex-start;bottom:26vh;padding:0}
 #awi-wel .w-bar{left:48%;right:auto;bottom:14vh;justify-content:flex-start;padding:0}
}
@media (prefers-reduced-motion:reduce){#awi-wel *{animation-duration:.01s!important;animation-delay:0s!important}}
</style>
<div class="w-grid"></div><div class="w-sweep"></div>
<div class="w-stage">
 <div class="w-disc"></div><div class="w-ring"></div>
 <img class="w-awi skip-lazy" data-no-lazy="1" decoding="async" src="__IMG__" alt="AWI, Sales Consultant BYD Haka Karebosi Makassar" width="320" height="1000">
 </div>
<div class="w-floor"></div>
<div class="w-txt">
 <div class="w-hi">Halo, saya</div>
 <div class="w-name"><span>A</span><span>W</span><span>I</span></div>
 <div class="w-full">Muh Munawir Shadzali</div>
 <div class="w-role">Sales Consultant · BYD Haka Karebosi Makassar</div>
</div>
<div class="w-tag">Beli <b>BYD</b>, Ingat <b>AWI</b>.</div>
<div class="w-chips"><span>⚡ Harga OTR Makassar</span><span>🚗 Test Drive</span><span>💳 Simulasi Kredit DP 15%</span></div>
<div class="w-bar"><button type="button" class="w-go" id="awi-wel-go">Masuk ke Website →<i></i></button></div>
<div class="w-top"><button type="button" class="w-snd" id="awi-wel-snd">🔊 Musik</button><button type="button" id="awi-wel-skip">Lewati ✕</button></div>
<audio id="awi-wel-aud" src="__MP3__" preload="auto"></audio>
</div>
AWITPL;
	$js = <<<'AWIJS'
(function(){try{if(sessionStorage.getItem('awiWel'))return;sessionStorage.setItem('awiWel','1');}catch(e){}if(/bot|crawl|spider|slurp|lighthouse|pagespeed|headless/i.test(navigator.userAgent))return;var tp=document.getElementById('awi-wel-tpl');if(!tp||!tp.content)return;document.body.appendChild(tp.content.cloneNode(true));(function(){
 var w=document.getElementById('awi-wel'),au=document.getElementById('awi-wel-aud'),snd=document.getElementById('awi-wel-snd'),done=false,on=false;
 document.documentElement.style.overflow='hidden';
 function close(){if(done)return;done=true;w.classList.add('out');try{var v=au.volume,f=setInterval(function(){v-=.1;if(v<=0){clearInterval(f);au.pause();}else au.volume=v;},60);}catch(e){}
  setTimeout(function(){document.documentElement.style.overflow='';w.remove();},650);
  try{sessionStorage.setItem('awiWel','1');}catch(e){}}
 function play(){au.volume=.85;var p=au.play();on=true;snd.textContent='🔊 On';snd.classList.remove('pulse');if(p&&p.catch)p.catch(function(){on=false;snd.textContent='🔇 Ketuk untuk musik';snd.classList.add('pulse');});}
 snd.addEventListener('click',function(e){e.stopPropagation();if(on){au.pause();on=false;snd.textContent='🔇 Musik';}else play();});
 document.getElementById('awi-wel-skip').addEventListener('click',function(e){e.stopPropagation();close();});
 document.getElementById('awi-wel-go').addEventListener('click',function(e){e.stopPropagation();close();});
 w.addEventListener('click',function(){if(!on)play();});
 play();
 var t=setTimeout(close,7600);
 au.addEventListener('play',function(){clearTimeout(t);t=setTimeout(close,8800);});
 document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});
})();})();
AWIJS;
	$img = 'https://byd-makassar.id/wp-content/uploads/2026/11/awi-welcome-sales-byd-makassar.webp';
	$mp3 = 'https://byd-makassar.id/wp-content/uploads/2026/11/awi-byd-haka-auto-karebosi-jingle.mp3';
	echo '<template id="awi-wel-tpl">' . str_replace( array( '__IMG__', '__MP3__' ), array( $img, $mp3 ), $tpl ) . '</template>';
	echo '<script data-no-optimize="1" data-no-defer="1" data-cfasync="false">' . $js . '</script>';
}
add_action( 'wp_body_open', 'awi_welcome_out', 1 );
